import pytest


class BadInput(Exception):
    def __init__(self, text: str) -> None:
        self.text = text


def sum_parsed(xs: list[str]) -> int:
    """Parse every string in xs as an integer and return their sum.

    Strings are parsed in order. The first string that is not an integer
    raises BadInput carrying that exact string. An empty list sums to 0.
    """
    total = 0
    for s in xs:
        try:
            total += int(s)
        except ValueError:
            raise BadInput(s) from None
    return total


def test_sum_basic() -> None:
    assert sum_parsed(["1", "2", "3"]) == 6


def test_sum_empty() -> None:
    assert sum_parsed([]) == 0


def test_sum_negative_numbers() -> None:
    assert sum_parsed(["-5", "10", "-2"]) == 3


def test_sum_single() -> None:
    assert sum_parsed(["42"]) == 42


def test_bad_input_carries_text() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["1", "abc", "3"])
    assert exc.value.text == "abc"


def test_first_bad_string_is_reported() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["1", "x", "y"])
    assert exc.value.text == "x"


def test_empty_string_is_bad() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["1", ""])
    assert exc.value.text == ""


def test_float_string_is_bad() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["2", "3.5"])
    assert exc.value.text == "3.5"


def test_bad_first_element() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["nope", "1"])
    assert exc.value.text == "nope"
